nal\n  ( -- * Positions\n    Pos (..)\n  , Span (..)\n    -- * Errors\n  , Expected (..)\n  , ParseError (..)\n  , renderParseError\n    -- * Running a parser\n  , Config (..)\n  , defaultConfig\n  , Stats (..)\n  , runParser\n    -- * The parser type\n  , P\n  , ST\n  , Text\n    -- * Memo tables\n  , Table\n  , ArgTable\n  , newTable\n  , newArgTable\n  , memo\n  , memoArg\n  , memoLR\n  , nomemo\n    -- * Terminals\n  , lit\n  , cls\n  , anyChar\n    -- * Combinators\n  , choice\n  , many\n  , many1\n  , skipMany\n  , skipMany1\n  , optional\n  , skipOptional\n  , andP\n  , notP\n  , capture\n  , predicate\n  , withCol\n    -- * Context\n  , getOffset\n  , spanFrom\n  , askStore\n    -- * Syntax trees (ADR 0019)\n  , SyntaxKind (..)\n  , Child\n  , SyntaxNode\n  , SyntaxToken\n  , SyntaxElement\n  , syntaxRoot\n  , syntaxKind\n  , labeledElements\n  , labeledNode\n  , labeledToken\n  , labeledNodes\n  , labeledTokens\n  , node\n  , token\n  , plain\n  , label\n  , manyS\n  , many1S\n  , optionalS\n  , captureS\n  , labelText\n  , touch\n    -- * Labelled failures and recovery (ADR 0021)\n  , SyntaxError (..)\n  , runParserRecover\n  , runSyntaxRecover\n  , labeled\n  , labeledS\n  , voidP\n  , voidS\n  ) where\n\nimport Control.Monad (ap, when)\nimport Control.Monad.ST (ST, runST)\nimport Data.Array.Unboxed ((!))\nimport Data.IntMap.Strict (IntMap)\nimport Data.IntSet (IntSet)\nimport qualified Data.IntSet as IS\nimport Data.List (partition, sortOn)\nimport qualified Data.IntMap.Strict as IM\nimport Data.Map.Strict (Map)\nimport qualified Data.Map.Strict as M\nimport Data.STRef (STRef, modifySTRef', newSTRef, readSTRef, writeSTRef)\nimport Data.Set (Set)\nimport qualified Data.Set as S\nimport Data.Text (Text)\nimport qualified Data.Text as T\nimport qualified Data.Text.Unsafe as TU\nimport Peg.Runtime.Position\nimport Peg.Runtime.Syntax\n\n-- | A range of the input, from 'spanStart' (inclusive) to 'spanEnd'\n-- (exclusive).\ndata Span = Span\n  { spanStart :: !Pos\n  , spanEnd :: !Pos\n  }\n  deriving (Eq, Ord, Show)\n\n-- | Something the parser expected to find at the position of a failure.\n--\n-- The constructor order defines the order in which expectations are listed.\ndata Expected\n  = -- | A literal, as written in the grammar (including its quotes).\n    ExpectedLiteral !Text\n  | -- | A character class, as written in the grammar.\n    ExpectedClass !Text\n  | -- | Any single character.\n    ExpectedAny\n  | -- | The end of the input.\n    ExpectedEnd\n  deriving (Eq, Ord, Show)\n\n-- | Why a parse failed. 'renderParseError' turns it into a message.\n--\n-- When several alternatives fail, the error is the one that got farthest:\n-- 'parseErrorPos' is the farthest position any terminal was tried at, and\n-- 'parseErrorExpected' collects every terminal that failed there. Failures\n-- inside negative lookahead and semantic predicates are not reported.\ndata ParseError = ParseError\n  { parseErrorPos :: !Pos\n  -- ^ The farthest position the parser reached.\n  , parseErrorExpected :: !(Set Expected)\n  -- ^ The terminals that were tried and failed at that position.\n  , parseErrorLabel :: !(Maybe Text)\n  -- ^ The label of the labelled failure that stopped the parse, if any\n  -- (ADR 0021).\n  }\n  deriving (Eq, Show)\n\n-- | A syntax error that a recovering parse recovered from (ADR 0021).\n--\n-- The recovering entry points of a generated module (@parseRecover@,\n-- @parseSyntaxRecover@) return these sorted by position:\n--\n-- @\n-- case parseRecover src of\n--   (value, errs) -> do\n--     forM_ errs $ \\\\e -> do\n--       let p = syntaxErrorPos e\n--       putStrLn (show (posLine p) ++ \\\":\\\" ++ show (posColumn p) ++ \\\": \\\" ++ maybe \\\"unexpected input\\\" T.unpack (syntaxErrorLabel e))\n--     print value  -- Nothing only if the start rule could not be recovered\n-- @\ndata SyntaxError = SyntaxError\n  { syntaxErrorLabel :: !(Maybe Text)\n  -- ^ The label that was thrown. 'Nothing' for input left over after the\n  -- start rule and for a start rule that could not be recovered.\n  , syntaxErrorRange :: !(Int, Int)\n  -- ^ The byte range the recovery skipped. It is empty when the recovery\n  -- consumed nothing.\n  , syntaxErrorPos :: Pos\n  -- ^ The position of the start of the range. Computed when used: the\n  -- column takes time proportional to the length of the line.\n  , syntaxErrorExpected :: !(Set Expected)\n  -- ^ What the parser expected at the farthest failure of the labelled\n  -- expression.\n  }\n  deriving (Eq, Show)\n\n-- | Render an error as @line:column: expected A, B or C@.\n--\n-- The expectations are listed in the order of 'Expected': literals and\n-- classes as written in the grammar, then @any character@, then\n-- @end of input@. With no expectation the message is @parse error@. The\n-- label of 'parseErrorLabel' is not included; map it to a message of your\n-- own if the grammar uses labels.\n--\n-- @\n-- case parse \\\"1 +\\\" of\n--   Left err -> TIO.putStrLn (renderParseError err)  -- 1:4: expected \\'(\\' or [0-9]\n--   Right v -> print v\n-- @\nrenderParseError :: ParseError -> Text\nrenderParseError e =\n  T.concat\n    [ T.pack (show (posLine p))\n    , \":\"\n    , T.pack (show (posColumn p))\n    , \": \"\n    , case map renderExpected (S.toAscList (parseErrorExpected e)) of\n        [] -> \"parse error\"\n        xs -> \"expected \" <> joinOr xs\n    ]\n  where\n    p = parseErrorPos e\n    joinOr [x] = x\n    joinOr xs = T.intercalate \", \" (init xs) <> \" or \" <> last xs\n\nrenderExpected :: Expected -> Text\nrenderExpected = \\case\n  ExpectedLiteral t -> t\n  ExpectedClass t -> t\n  ExpectedAny -> \"any character\"\n  ExpectedEnd -> \"end of input\"\n\n-- | Options for a parse. Generated parsers use 'defaultConfig', with\n-- 'cfgTabstop' set by @%tabstop@; the other settings exist for testing the\n-- runtime and the generator (the @peg'parseWith@ entry point that\n-- @peg-hs gen --debug-entry@ adds).\ndata Config = Config\n  { cfgMemo :: !Bool\n  -- ^ Memoise rules that are not left-recursive. Left-recursive rules are\n  -- always memoised, since their semantics depends on the memo table.\n  , cfgDiscard :: !Bool\n  -- ^ Discard memo entries that depend on the seed of a left recursion\n  -- growth loop at the end of each of its iterations. Turning this off is\n  -- only useful for tests.\n  , cfgDiscardAll :: !Bool\n  -- ^ Discard every memo entry written during an iteration instead, whether\n  -- it depends on the seed or not (ADR 0013). Only useful for comparing the\n  -- two in tests.\n  , cfgCount :: !Bool\n  -- ^ Count rule body evaluations into t'Stats'.\n  , cfgTabstop :: !Int\n  -- ^ Tab stop used by the column passed to predicates and rule arguments\n  -- (@_col@). 0 means a tab counts as a single column.\n  , cfgRecover :: !Bool\n  -- ^ Recover from labelled failures with the recovery rules (ADR 0021).\n  -- 'runParserRecover' and 'runSyntaxRecover' turn it on and 'runParser'\n  -- turns it off, so setting it has no effect.\n  }\n  deriving (Eq, Show)\n\n-- | Memoisation and discarding on, counting off, no tab stop.\ndefaultConfig :: Config\ndefaultConfig = Config {cfgMemo = True, cfgDiscard = True, cfgDiscardAll = False, cfgCount = False, cfgTabstop = 0, cfgRecover = False}\n\n-- | Counters collected when 'cfgCount' is on.\ndata Stats = Stats\n  { statsEvaluations :: !(Map (Text, Int) Int)\n  -- ^ How many times the body of each rule was evaluated at each offset.\n  , statsMemoEntries :: !Int\n  -- ^ The number of memo entries alive at the end of the parse.\n  , statsEntriesByRule :: !(Map Text Int)\n  -- ^ The memo entries alive at the end of the parse, by rule.\n  }\n  deriving (Eq, Show)\n\nemptyStats :: Stats\nemptyStats = Stats M.empty 0 M.empty\n\ndata Failure\n  = NoFailure\n  | Failure !Int !(Set Expected)\n  deriving (Eq, Show)\n\nmergeFailure :: Failure -> Failure -> Failure\nmergeFailure NoFailure f = f\nmergeFailure f NoFailure = f\nmergeFailure a@(Failure i xs) b@(Failure j ys)\n  | i > j = a\n  | i < j = b\n  | otherwise = Failure i (S.union xs ys)\n\n-- | The result of running a parser at an offset.\ndata Res a\n  = Ok !Int a\n  | Fail\n  | -- | A labelled failure: the position where the labelled expression was\n    -- tried and the label (ADR 0021).\n    Throw !Int !Text\n\n-- The syntax errors recorded so far: how many, and the errors, newest first.\n-- The count makes saving and comparing the log constant time.\ndata ErrLog = ErrLog !Int [SyntaxError]\n\n-- The errors recorded by one evaluation: the first @n@ elements of a log.\n-- The list is shared with the log, so storing it in a memo entry copies\n-- nothing.\ndata ErrSlice = ErrSlice !Int [SyntaxError]\n\nnoErrors :: ErrSlice\nnoErrors = ErrSlice 0 []\n\n-- Re-type a result that is not a success.\nfailed :: Res a -> Res b\nfailed (Throw i l) = Throw i l\nfailed _ = Fail\n\ndata Ctx r s = Ctx\n  { ctxInput :: !Text\n  , ctxLen :: !Int\n  , ctxStore :: r\n  , ctxFail :: !(STRef s Failure)\n  , ctxErrors :: !(STRef s ErrLog)\n  , -- | The growth loops whose seeds the evaluation in progress has read,\n    -- numbered from 1 for the outermost loop running (ADR 0024).\n    ctxDeps :: !(STRef s IntSet)\n  , -- | The number of growth loops running.\n    ctxDepth :: !(STRef s Int)\n  , -- | For each iteration of the growth loops running, innermost first, the\n    -- memo entries written that may have to be discarded: their dependencies\n    -- and how to remove them.\n    ctxLogs :: !(STRef s [[(IntSet, ST s ())]])\n  , ctxStats :: !(STRef s Stats)\n  , ctxConfig :: !Config\n  , ctxLines :: LineIndex\n  }\n\n-- | A parser over a generated store @r@ in the state thread @s@.\nnewtype P r s a = P {unP :: Ctx r s -> Int -> ST s (Res a)}\n\ninstance Functor (P r s) where\n  fmap f (P p) =\n    P $ \\c i ->\n      p c i >>= \\case\n        Ok j x -> pure (Ok j (f x))\n        bad -> pure (failed bad)\n\ninstance Applicative (P r s) where\n  pure x = P $ \\_ i -> pure (Ok i x)\n  (<*>) = ap\n\ninstance Monad (P r s) where\n  P p >>= k =\n    P $ \\c i ->\n      p c i >>= \\case\n        Ok j x -> unP (k x) c j\n        bad -> pure (failed bad)\n\n-- | Run the start rule over the whole input. The arguments are the\n-- configuration, the action that creates the generated store of memo\n-- tables, the start rule and the input.\n--\n-- The parse succeeds only if the start rule consumes the entire input;\n-- otherwise 'ExpectedEnd' is expected where the match ended. A label\n-- thrown by 'labeled' stops the parse and is reported in\n-- 'parseErrorLabel'; recovery is off, whatever 'cfgRecover' says.\n--\n-- A generated entry point calls it like this (names simplified):\n--\n-- @\n-- parse :: Text -> Either ParseError Expr\n-- parse input = fst (runParser config newStore rule_Expr input)\n-- @\nrunParser\n  :: Config\n  -> (forall s. ST s (store s))\n  -> (forall s. P (store s) s a)\n  -> Text\n  -> (Either ParseError a, Stats)\nrunParser cfg mkStore start input = runST $ do\n  ctx <- newCtx cfg {cfgRecover = False} mkStore input\n  r <- unP start ctx 0\n  res <- case r of\n    Ok j x | j == ctxLen ctx -> pure (Right x)\n    Ok j _ -> do\n      mergeFail ctx (Failure j (S.singleton ExpectedEnd))\n      Left <$> currentError ctx Nothing\n    Throw _ l -> Left <$> currentError ctx (Just l)\n    Fail -> Left <$> currentError ctx Nothing\n  s <- readSTRef (ctxStats ctx)\n  pure (res, s)\n\nnewCtx :: Config -> ST s (store s) -> Text -> ST s (Ctx (store s) s)\nnewCtx cfg mkStore input = do\n  st <- mkStore\n  fref <- newSTRef NoFailure\n  errs <- newSTRef (ErrLog 0 [])\n  logs <- newSTRef []\n  deps <- newSTRef IS.empty\n  depth <- newSTRef 0\n  stats <- newSTRef emptyStats\n  pure\n    Ctx\n      { ctxInput = input\n      , ctxLen = TU.lengthWord8 input\n      , ctxStore = st\n      , ctxFail = fref\n      , ctxErrors = errs\n      , ctxDeps = deps\n      , ctxDepth = depth\n      , ctxLogs = logs\n      , ctxStats = stats\n      , ctxConfig = cfg\n      , ctxLines = lineIndex input\n      }\n\ncurrentError :: Ctx r s -> Maybe Text -> ST s ParseError\ncurrentError ctx failLabel =\n  readSTRef (ctxFail ctx) >>= \\case\n    NoFailure -> pure (ParseError (posAt ctx 0) S.empty failLabel)\n    Failure i xs -> pure (ParseError (posAt ctx i) xs failLabel)\n\n-- | Run the start rule over the whole input, recovering from labelled\n-- failures (ADR 0021). The value is 'Nothing' only if the start rule could\n-- not be recovered. Errors are sorted by position. Input left over after\n-- the start rule is reported as a t'SyntaxError' without a label, and so\n-- is a start rule that could not be recovered.\nrunParserRecover\n  :: Config\n  -> (forall s. ST s (store s))\n  -> (forall s. P (store s) s a)\n  -> Text\n  -> (Maybe a, [SyntaxError], Stats)\nrunParserRecover cfg mkStore start input =\n  let (value, errs, st) = recoverCore cfg mkStore start input\n   in (fmap snd value, errs, st)\n\n-- | 'runParserRecover' for a grammar with @%syntax@. Always returns a tree:\n-- input left over after the start rule, or the whole input if the start\n-- rule could not be recovered, becomes an error node (of kind\n-- 'Peg.Runtime.Syntax.errorKind'). The t'SyntaxKind' is the kind of the\n-- root node, used when the children do not form a single node that covers\n-- the input (see 'syntaxRoot').\nrunSyntaxRecover\n  :: Config\n  -> (forall s. ST s (store s))\n  -> (forall s. P (store s) s (a, [Child]))\n  -> SyntaxKind\n  -> Text\n  -> (SyntaxNode, [SyntaxError], Stats)\nrunSyntaxRecover cfg mkStore start k input =\n  let (value, errs, st) = recoverCore cfg mkStore start input\n      len = TU.lengthWord8 input\n      kids = case value of\n        Just (j, (_, ks))\n          | j == len -> ks\n          | otherwise -> ks ++ [CNode errorKind j len [] Nothing]\n        Nothing -> [CNode errorKind 0 len [] Nothing]\n   in (syntaxRoot input k kids, errs, st)\n\n-- The end of the start rule's match and its value, with all errors,\n-- including the one for left over input or an unrecoverable start rule.\nrecoverCore\n  :: Config\n  -> (forall s. ST s (store s))\n  -> (forall s. P (store s) s a)\n  -> Text\n  -> (Maybe (Int, a), [SyntaxError], Stats)\nrecoverCore cfg mkStore start input = runST $ do\n  ctx <- newCtx cfg {cfgRecover = True} mkStore input\n  r <- unP start ctx 0\n  errs <- (\\(ErrLog _ xs) -> reverse xs) <$> readSTRef (ctxErrors ctx)\n  let len = ctxLen ctx\n  (value, all') <- case r of\n    Ok j x | j == len -> pure (Just (j, x), errs)\n    Ok j x -> do\n      mergeFail ctx (Failure j (S.singleton ExpectedEnd))\n      e <- wholeError ctx Nothing j\n      pure (Just (j, x), errs ++ [e])\n    Throw _ l -> (\\e -> (Nothing, [e])) <$> wholeError ctx (Just l) 0\n    Fail -> (\\e -> (Nothing, [e])) <$> wholeError ctx Nothing 0\n  st <- readSTRef (ctxStats ctx)\n  pure (value, sortOn syntaxErrorRange all', st)\n  where\n    wholeError ctx failLabel from = do\n      expected <-\n        readSTRef (ctxFail ctx) >>= \\case\n          NoFailure -> pure S.empty\n          Failure _ xs -> pure xs\n      pure (SyntaxError failLabel (from, ctxLen ctx) (posAt ctx from) expected)\n\n-- Positions ------------------------------------------------------------------\n\nslice :: Text -> Int -> Int -> Text\nslice t from to = TU.takeWord8 (to - from) (TU.dropWord8 from t)\n\nposAt :: Ctx r s -> Int -> Pos\nposAt ctx = posIn (ctxInput ctx) (ctxLines ctx)\n\n-- The 0-based column of an offset, expanding tabs to 'cfgTabstop'.\ncolAt :: Ctx r s -> Int -> Int\ncolAt ctx off = T.foldl' step 0 (slice (ctxInput ctx) start off)\n  where\n    start = ctxLines ctx ! lineOf (ctxLines ctx) off\n    ts = cfgTabstop (ctxConfig ctx)\n    step col ch\n      | ch == '\\t' && ts > 0 = (col `div` ts + 1) * ts\n      | otherwise = col + 1\n\n-- Failures ---------------------------------------------------------------------\n\nmergeFail :: Ctx r s -> Failure -> ST s ()\nmergeFail ctx f = modifySTRef' (ctxFail ctx) (`mergeFailure` f)\n\nfailAt :: Ctx r s -> Int -> Expected -> ST s (Res a)\nfailAt ctx i e = Fail <$ mergeFail ctx (Failure i (S.singleton e))\n\n-- Terminals ------------------------------------------------------------------\n\n-- | Match a literal. The first argument is the text to match, the second the\n-- literal as written in the grammar, used in error messages.\nlit :: String -> String -> P r s ()\nlit s orig = P $ \\c i ->\n  if t `T.isPrefixOf` TU.dropWord8 i (ctxInput c)\n    then pure (Ok (i + n) ())\n    else failAt c i expected\n  where\n    t = T.pack s\n    n = TU.lengthWord8 t\n    expected = ExpectedLiteral (T.pack orig)\n\n-- | Match one character in any of the inclusive ranges. The second argument\n-- is the class as written in the grammar.\ncls :: [(Char, Char)] -> String -> P r s ()\ncls ranges orig = P $ \\c i ->\n  if i < ctxLen c\n    then\n      let TU.Iter ch d = TU.iter (ctxInput c) i\n       in if any (\\(a, b) -> a <= ch && ch <= b) ranges\n            then pure (Ok (i + d) ())\n            else failAt c i expected\n    else failAt c i expected\n  where\n    expected = ExpectedClass (T.pack orig)\n\n-- | Match any single code point.\nanyChar :: P r s ()\nanyChar = P $ \\c i ->\n  if i < ctxLen c\n    then let TU.Iter _ d = TU.iter (ctxInput c) i in pure (Ok (i + d) ())\n    else failAt c i ExpectedAny\n\n-- Combinators ----------------------------------------------------------------\n\n-- | Ordered choice: try each alternative in turn and take the first success.\nchoice :: [P r s a] -> P r s a\nchoice ps = P $ \\c i -> do\n  saved <- saveErrors c\n  let go [] = pure Fail\n      go (p : rest) =\n        unP p c i >>= \\case\n          r@Ok {} -> pure r\n          Fail -> restoreErrors c saved >> go rest\n          r -> restoreErrors c saved >> pure r\n  go ps\n\n-- Errors are only recorded in recovery mode, so only then are they saved\n-- and restored when an attempt is abandoned.\nsaveErrors :: Ctx r s -> ST s (Maybe ErrLog)\nsaveErrors c\n  | cfgRecover (ctxConfig c) = Just <$> readSTRef (ctxErrors c)\n  | otherwise = pure Nothing\n\nrestoreErrors :: Ctx r s -> Maybe ErrLog -> ST s ()\nrestoreErrors c = maybe (pure ()) (writeSTRef (ctxErrors c))\n\n-- | Zero or more repetitions, collecting the results.\nmany :: P r s a -> P r s [a]\nmany p = P $ \\c i ->\n  let go j acc = do\n        saved <- saveErrors c\n        unP p c j >>= \\case\n          Ok k x | k > j -> go k (x : acc)\n          Throw t l -> restoreErrors c saved >> pure (Throw t l)\n          _ -> restoreErrors c saved >> pure (Ok j (reverse acc))\n   in go i []\n\n-- | One or more repetitions, collecting the results.\nmany1 :: P r s a -> P r s [a]\nmany1 p = (:) <$> p <*> many p\n\n-- | Zero or more repetitions, discarding the results.\nskipMany :: P r s a -> P r s ()\nskipMany p = P $ \\c i ->\n  let go j = do\n        saved <- saveErrors c\n        unP p c j >>= \\case\n          Ok k _ | k > j -> go k\n          Throw t l -> restoreErrors c saved >> pure (Throw t l)\n          _ -> restoreErrors c saved >> pure (Ok j ())\n   in go i\n\n-- | One or more repetitions, discarding the results.\nskipMany1 :: P r s a -> P r s ()\nskipMany1 p = p >> skipMany p\n\n-- | An optional match.\noptional :: P r s a -> P r s (Maybe a)\noptional p = P $ \\c i -> do\n  saved <- saveErrors c\n  unP p c i >>= \\case\n    Ok j x -> pure (Ok j (Just x))\n    Fail -> restoreErrors c saved >> pure (Ok i Nothing)\n    r -> restoreErrors c saved >> pure (failed r)\n\n-- | An optional match, discarding the result.\nskipOptional :: P r s a -> P r s ()\nskipOptional p = () <$ optional p\n\n-- | Positive lookahead. Consumes no input. A label thrown inside it is an\n-- ordinary failure (ADR 0021).\nandP :: P r s a -> P r s ()\nandP p = P $ \\c i -> do\n  saved <- saveErrors c\n  r <- unP p c i\n  restoreErrors c saved\n  case r of\n    Ok _ _ -> pure (Ok i ())\n    _ -> pure Fail\n\n-- | Negative lookahead. Consumes no input, and failures inside it are not\n-- reported.\nnotP :: P r s a -> P r s ()\nnotP p = P $ \\c i -> do\n  saved <- readSTRef (ctxFail c)\n  savedErrors <- saveErrors c\n  r <- unP p c i\n  writeSTRef (ctxFail c) saved\n  restoreErrors c savedErrors\n  case r of\n    Ok _ _ -> pure Fail\n    _ -> pure (Ok i ())\n\n-- | The input consumed by a parser.\ncapture :: P r s a -> P r s Text\ncapture p = P $ \\c i ->\n  unP p c i >>= \\case\n    Ok j _ -> pure (Ok j (slice (ctxInput c) i j))\n    bad -> pure (failed bad)\n\n-- | A semantic predicate. The function receives the current 0-based column.\n-- Consumes no input, and a failure is not reported.\npredicate :: (Int -> Bool) -> P r s ()\npredicate f = P $ \\c i ->\n  pure (if f (colAt c i) then Ok i () else Fail)\n\n-- | Pass the current 0-based column to a parser.\nwithCol :: (Int -> P r s a) -> P r s a\nwithCol f = P $ \\c i -> unP (f (colAt c i)) c i\n\n-- Context --------------------------------------------------------------------\n\n-- | The current byte offset.\ngetOffset :: P r s Int\ngetOffset = P $ \\_ i -> pure (Ok i i)\n\n-- | The span from a byte offset to the current offset. The positions are\n-- computed lazily.\nspanFrom :: Int -> P r s Span\nspanFrom start = P $ \\c i -> pure (Ok i (Span (posAt c start) (posAt c i)))\n\n-- | Read a field of the generated store.\naskStore :: (r -> a) -> P r s a\naskStore f = P $ \\c i -> pure (Ok i (f (ctxStore c)))\n\n-- Memo tables ----------------------------------------------------------------\n\n-- A memoised result with its failure record, the syntax errors recorded\n-- while evaluating it (newest first), and the growth loops whose seeds it\n-- depends on.\ndata Entry a = Entry !(Res a) !Failure !ErrSlice !IntSet\n\n-- | A sparse memo table for one rule, keyed by byte offset.\ntype Table s a = STRef s (IntMap (Entry a))\n\n-- | A sparse memo table for a rule with arguments.\ntype ArgTable s k a = STRef s (IntMap (Map k (Entry a)))\n\n-- | An empty memo table.\nnewTable :: ST s (Table s a)\nnewTable = newSTRef IM.empty\n\n-- | An empty memo table for a rule with arguments.\nnewArgTable :: ST s (ArgTable s k a)\nnewArgTable = newSTRef IM.empty\n\ncountEval :: Ctx r s -> Text -> Int -> ST s ()\ncountEval c name i =\n  when (cfgCount (ctxConfig c)) $\n    modifySTRef' (ctxStats c) $ \\st ->\n      st {statsEvaluations = M.insertWith (+) (name, i) 1 (statsEvaluations st)}\n\nbumpEntries :: Ctx r s -> Text -> Int -> ST s ()\nbumpEntries c name d =\n  when (cfgCount (ctxConfig c)) $\n    modifySTRef' (ctxStats c) $ \\st ->\n      st\n        { statsMemoEntries = statsMemoEntries st + d\n        , statsEntriesByRule = M.insertWith (+) name d (statsEntriesByRule st)\n        }\n\n-- Evaluate a rule body with its own failure record, so that the failure can\n-- be stored in the memo entry and replayed on a hit. In recovery mode the\n-- syntax errors recorded by a successful evaluation are returned as well;\n-- those of an unsuccessful one are discarded.\nevalBody :: Ctx r s -> Text -> Int -> P r s a -> ST s (Res a, Failure, ErrSlice, IntSet)\nevalBody c name i body = do\n  countEval c name i\n  saved <- readSTRef (ctxFail c)\n  writeSTRef (ctxFail c) NoFailure\n  savedDeps <- readSTRef (ctxDeps c)\n  writeSTRef (ctxDeps c) IS.empty\n  before <- saveErrors c\n  r <- unP body c i\n  f <- readSTRef (ctxFail c)\n  writeSTRef (ctxFail c) (mergeFailure saved f)\n  d <- readSTRef (ctxDeps c)\n  writeSTRef (ctxDeps c) (IS.union savedDeps d)\n  new <- case r of\n    Ok {} -> newErrors c before\n    _ -> noErrors <$ restoreErrors c before\n  pure (r, f, new, d)\n\n-- The errors recorded since a saved state.\nnewErrors :: Ctx r s -> Maybe ErrLog -> ST s ErrSlice\nnewErrors _ Nothing = pure noErrors\nnewErrors c (Just (ErrLog old _)) = do\n  ErrLog now xs <- readSTRef (ctxErrors c)\n  pure (ErrSlice (now - old) xs)\n\n-- Add the errors of a slice to the log.\nappendSlice :: Ctx r s -> ErrSlice -> ST s ()\nappendSlice _ (ErrSlice 0 _) = pure ()\nappendSlice c (ErrSlice k xs) = modifySTRef' (ctxErrors c) (\\(ErrLog n ys) -> ErrLog (n + k) (take k xs ++ ys))\n\n-- Replay a memo entry.\nreplay :: Ctx r s -> Entry a -> ST s (Res a)\nreplay c (Entry r f errs d) = do\n  mergeFail c f\n  when (not (IS.null d)) (modifySTRef' (ctxDeps c) (IS.union d))\n  case r of\n    Ok {} -> appendSlice c errs\n    _ -> pure ()\n  pure r\n\n-- Record how to remove a memo entry in the innermost growth loop, if any.\n-- An entry that depends on no seed is final and is not recorded, unless\n-- every entry is to be discarded ('cfgDiscardAll').\nlogUndo :: Ctx r s -> IntSet -> ST s () -> ST s ()\nlogUndo c deps undo =\n  when (not (IS.null deps) || cfgDiscardAll (ctxConfig c)) $\n    readSTRef (ctxLogs c) >>= \\case\n      l : ls -> writeSTRef (ctxLogs c) (((deps, undo) : l) : ls)\n      [] -> pure ()\n\n-- End an iteration of the growth loop numbered @k@: discard the entries\n-- that depend on its seed, and pass the others, which depend only on the\n-- seeds of loops further out, to the iteration of the enclosing loop.\nendIteration :: Ctx r s -> Int -> ST s ()\nendIteration c k =\n  readSTRef (ctxLogs c) >>= \\case\n    l : ls -> do\n      let cfg = ctxConfig c\n          (stale, kept)\n            | cfgDiscardAll cfg = (l, [])\n            | otherwise = partition (IS.member k . fst) l\n      when (cfgDiscard cfg) (mapM_ snd stale)\n      writeSTRef (ctxLogs c) $ case ls of\n        o : os -> (kept ++ o) : os\n        [] -> []\n    [] -> pure ()\n\n-- | Memoise a rule that does not take part in left recursion.\nmemo :: (r -> Table s a) -> String -> P r s a -> P r s a\nmemo sel rawName body = P $ \\c i ->\n  if not (cfgMemo (ctxConfig c))\n    then (\\(r, _, _, _) -> r) <$> evalBody c name i body\n    else do\n      let t = sel (ctxStore c)\n      IM.lookup i <$> readSTRef t >>= \\case\n        Just e -> replay c e\n        Nothing -> do\n          (r, f, errs, d) <- evalBody c name i body\n          modifySTRef' t (IM.insert i (Entry r f errs d))\n          bumpEntries c name 1\n          logUndo c d (modifySTRef' t (IM.delete i) >> bumpEntries c name (-1))\n          pure r\n  where\n    name = T.pack rawName\n\n-- | Memoise a rule with arguments. The arguments are part of the key.\nmemoArg :: Ord k => (r -> ArgTable s k a) -> String -> k -> P r s a -> P r s a\nmemoArg sel rawName k body = P $ \\c i ->\n  if not (cfgMemo (ctxConfig c))\n    then (\\(r, _, _, _) -> r) <$> evalBody c name i body\n    else do\n      let t = sel (ctxStore c)\n      (IM.lookup i <$> readSTRef t) >>= \\m -> case m >>= M.lookup k of\n        Just e -> replay c e\n        Nothing -> do\n          (r, f, errs, d) <- evalBody c name i body\n          modifySTRef' t (IM.insertWith M.union i (M.singleton k (Entry r f errs d)))\n          bumpEntries c name 1\n          logUndo c d (modifySTRef' t (IM.adjust (M.delete k) i) >> bumpEntries c name (-1))\n          pure r\n  where\n    name = T.pack rawName\n\n-- | A rule that is not memoised (@%nomemo@). Its body is evaluated on every\n-- call. The failure record is kept per evaluation as for memoised rules, so\n-- that turning memoisation off does not change the reported error.\nnomemo :: String -> P r s a -> P r s a\nnomemo rawName body = P $ \\c i -> (\\(r, _, _, _) -> r) <$> evalBody c name i body\n  where\n    name = T.pack rawName\n\n-- | Evaluate a rule that takes part in left recursion.\n--\n-- On the first call at an offset the memo entry is seeded with a failure,\n-- and the body is re-evaluated while each evaluation matches more input\n-- than the previous one. The longest match is the result. Entries that\n-- other rules wrote during an iteration may depend on the seed of that\n-- iteration; those that read the seed are discarded at the end of every\n-- iteration, and the others are kept (ADR 0024). 'cfgDiscard' and\n-- 'cfgDiscardAll' change this for tests.\nmemoLR :: (r -> Table s a) -> String -> P r s a -> P r s a\nmemoLR sel rawName body = P $ \\c i -> do\n  let t = sel (ctxStore c)\n  IM.lookup i <$> readSTRef t >>= \\case\n    Just e -> replay c e\n    Nothing -> do\n      saved <- readSTRef (ctxFail c)\n      writeSTRef (ctxFail c) NoFailure\n      savedDeps <- readSTRef (ctxDeps c)\n      depth <- readSTRef (ctxDepth c)\n      let k = depth + 1\n          -- Whoever reads the seed depends on this loop.\n          seed r errs = Entry r NoFailure errs (IS.singleton k)\n      writeSTRef (ctxDepth c) k\n      before <- saveErrors c\n      modifySTRef' t (IM.insert i (seed Fail noErrors))\n      bumpEntries c name 1\n      -- Each iteration starts from the errors before the growth, so that\n      -- only the errors of the iteration that is kept remain. The result\n      -- depends on the seeds read by every iteration, the last one included,\n      -- since that one decides where the growth stops.\n      let grow lastRes lastEnd lastErrs deps = do\n            countEval c name i\n            restoreErrors c before\n            writeSTRef (ctxDeps c) IS.empty\n            modifySTRef' (ctxLogs c) ([] :)\n            r <- unP body c i\n            d <- IS.union deps <$> readSTRef (ctxDeps c)\n            endIteration c k\n            case r of\n              Ok j x | j > lastEnd -> do\n                errs <- newErrors c before\n                modifySTRef' t (IM.insert i (seed (Ok j x) errs))\n                grow r j errs d\n              Throw {} -> pure (r, noErrors, d)\n              _ -> pure (lastRes, lastErrs, d)\n      (res, errs, d) <- grow Fail (-1) noErrors IS.empty\n      let deps = IS.delete k d\n      writeSTRef (ctxDepth c) depth\n      writeSTRef (ctxDeps c) (IS.union savedDeps deps)\n      restoreErrors c before\n      case res of\n        Ok {} -> appendSlice c errs\n        _ -> pure ()\n      f <- readSTRef (ctxFail c)\n      writeSTRef (ctxFail c) (mergeFailure saved f)\n      modifySTRef' t (IM.insert i (Entry res f errs deps))\n      logUndo c deps (modifySTRef' t (IM.delete i) >> bumpEntries c name (-1))\n      pure res\n  where\n    name = T.pack rawName\n\n-- Syntax trees -----------------------------------------------------------------\n\n-- In a grammar with @%syntax@, every parser returns its value together with\n-- the children it contributes to the syntax tree.\n\n-- | Record a rule invocation as a node.\nnode :: SyntaxKind -> P r s (a, [Child]) -> P r s (a, [Child])\nnode k p = P $ \\c i ->\n  unP p c i >>= \\case\n    Ok j (v, kids) -> pure (Ok j (v, [CNode k i j kids Nothing]))\n    bad -> pure (failed bad)\n\n-- | Record a rule invocation as a single token.\ntoken :: SyntaxKind -> P r s (a, [Child]) -> P r s (a, [Child])\ntoken k p = P $ \\c i ->\n  unP p c i >>= \\case\n    Ok j (v, _) -> pure (Ok j (v, [CToken k i j Nothing]))\n    bad -> pure (failed bad)\n\n-- | A parser that contributes nothing but text.\nplain :: P r s a -> P r s (a, [Child])\nplain = fmap (\\x -> (x, []))\n\n-- | Label the children of a bound expression. If it produced no children\n-- but consumed text, the text becomes a labelled token.\nlabel :: String -> P r s (a, [Child]) -> P r s (a, [Child])\nlabel rawLabel p = P $ \\c i ->\n  unP p c i >>= \\case\n    Ok j (v, kids)\n      | null kids && j > i -> pure (Ok j (v, [CToken textKind i j (Just l)]))\n      | otherwise -> pure (Ok j (v, map (setLabel l) kids))\n    bad -> pure (failed bad)\n  where\n    l = T.pack rawLabel\n\n-- | Zero or more repetitions in syntax mode.\nmanyS :: P r s (a, [Child]) -> P r s ([a], [Child])\nmanyS = fmap (\\xs -> (map fst xs, concatMap snd xs)) . many\n\n-- | One or more repetitions in syntax mode.\nmany1S :: P r s (a, [Child]) -> P r s ([a], [Child])\nmany1S = fmap (\\xs -> (map fst xs, concatMap snd xs)) . many1\n\n-- | An optional match in syntax mode.\noptionalS :: P r s (a, [Child]) -> P r s (Maybe a, [Child])\noptionalS = fmap (maybe (Nothing, []) (\\(v, k) -> (Just v, k))) . optional\n\n-- | The consumed text in syntax mode. The children are kept.\ncaptureS :: P r s (a, [Child]) -> P r s (Text, [Child])\ncaptureS p = P $ \\c i ->\n  unP p c i >>= \\case\n    Ok j (_, kids) -> pure (Ok j (slice (ctxInput c) i j, kids))\n    bad -> pure (failed bad)\n\n-- | A label or kind name from a string literal of generated code.\nlabelText :: String -> Text\nlabelText = T.pack\n\n-- | Mark a binding as used without evaluating it. In syntax mode a binding\n-- may exist only to label children in the tree.\ntouch :: a -> P r s ()\ntouch _ = pure ()\n\n-- Labelled failures (ADR 0021) ----------------------------------------------\n\n-- | @e ^label@. If the parser fails, throw the label at the position where\n-- it was tried. In recovery mode, a recovery parser for the label is run\n-- from that position instead; if it succeeds, its value is the result and\n-- a syntax error is recorded. A label thrown inside the recovery parser\n-- makes the recovery fail.\nlabeled :: String -> Maybe (P r s a) -> P r s a -> P r s a\nlabeled = labeledWith (\\_ _ v -> v)\n\n-- | 'labeled' in syntax mode: the recovered range becomes an error node\n-- whose children are those of the recovery rule.\nlabeledS :: String -> Maybe (P r s (a, [Child])) -> P r s (a, [Child]) -> P r s (a, [Child])\nlabeledS = labeledWith (\\i j (v, kids) -> (v, [CNode errorKind i j (unwrap kids) Nothing]))\n  where\n    unwrap [CNode _ _ _ ks Nothing] = ks\n    unwrap ks = ks\n\nlabeledWith :: (Int -> Int -> a -> a) -> String -> Maybe (P r s a) -> P r s a -> P r s a\nlabeledWith wrap rawLabel recovery p = P $ \\c i -> do\n  savedFail <- readSTRef (ctxFail c)\n  writeSTRef (ctxFail c) NoFailure\n  savedErrors <- saveErrors c\n  r <- unP p c i\n  local <- readSTRef (ctxFail c)\n  writeSTRef (ctxFail c) (mergeFailure savedFail local)\n  case r of\n    Fail -> do\n      restoreErrors c savedErrors\n      case recovery of\n        Just q | cfgRecover (ctxConfig c) ->\n          unP q c i >>= \\case\n            Ok j v -> do\n              let expected = case local of\n                    Failure _ xs -> xs\n                    NoFailure -> S.empty\n              modifySTRef' (ctxErrors c) (\\(ErrLog n xs) -> ErrLog (n + 1) (SyntaxError (Just l) (i, j) (posAt c i) expected : xs))\n              pure (Ok j (wrap i j v))\n            _ -> restoreErrors c savedErrors >> pure (Throw i l)\n        _ -> pure (Throw i l)\n    _ -> pure r\n  where\n    l = T.pack rawLabel\n\n-- | Discard the value of a recovery parser, for a label on an expression\n-- without a value.\nvoidP :: P r s a -> P r s ()\nvoidP = fmap (const ())\n\n-- | 'voidP' in syntax mode.\nvoidS :: P r s (a, [Child]) -> P r s ((), [Child])\nvoidS = fmap (\\(_, kids) -> ((), kids))\n")
  , ("Peg/Runtime/Position.hs", "-- | Positions in the input: byte offsets with lines and columns (ADR 0008,\n-- ADR 0014).\nmodule Peg.Runtime.Position\n  ( Pos (..)\n  , LineIndex\n  , lineIndex\n  , lineOf\n  , posIn\n  ) where\n\nimport Data.Array.Unboxed (UArray, bounds, listArray, (!))\nimport Data.Text (Text)\nimport qualified Data.Text as T\nimport qualified Data.Text.Unsafe as TU\n\n-- | A position in the input.\ndata Pos = Pos\n  { posOffset :: !Int\n  -- ^ Byte offset into the UTF-8 encoded input, starting at 0.\n  , posLine :: !Int\n  -- ^ Line number, starting at 1. Only LF starts a new line.\n  , posColumn :: !Int\n  -- ^ Column, starting at 1. Each Unicode code point, including a tab,\n  -- counts as one column.\n  }\n  deriving (Eq, Ord, Show)\n\n-- | The byte offsets where lines start.\ntype LineIndex = UArray Int Int\n\nlineIndex :: Text -> LineIndex\nlineIndex t = listArray (0, length starts - 1) starts\n  where\n    n = TU.lengthWord8 t\n    starts = 0 : go 0\n    go i\n      | i >= n = []\n      | otherwise =\n          let TU.Iter c d = TU.iter t i\n           in if c == '\\n' then (i + d) : go (i + d) else go (i + d)\n\n-- Index of the last line start that is <= the offset.\nlineOf :: LineIndex -> Int -> Int\nlineOf arr off = go lo hi\n  where\n    (lo, hi) = bounds arr\n    go a b\n      | a >= b = a\n      | otherwise =\n          let m = (a + b + 1) `div` 2\n           in if arr ! m <= off then go m b else go a (m - 1)\n\n-- | The position of a byte offset.\nposIn :: Text -> LineIndex -> Int -> Pos\nposIn input index off = Pos off (l + 1) (T.length (TU.takeWord8 (off - start) (TU.dropWord8 start input)) + 1)\n  where\n    l = lineOf index off\n    start = index ! l\n")
  , ("Peg/Runtime/Syntax.hs", "{-# LANGUAGE OverloadedStrings #-}\n\n-- | Lossless syntax trees (ADR 0019), after rust-analyzer's rowan.\n--\n-- A t'GreenNode' is an immutable tree of kinds and text: every byte of the\n-- input belongs to exactly one token, so the text of the tree is the input.\n-- t'SyntaxNode' and t'SyntaxToken' wrap green elements with their absolute\n-- offset and parent, and are what applications navigate.\n--\n-- Parsers generated from a grammar with @%syntax@ build these trees. For a\n-- grammar with the rules @Expr@ and @Num@, the generated module exports:\n--\n-- * @parseSyntax :: Text -> Either ParseError SyntaxNode@, and with labels\n--   (ADR 0021) @parseSyntaxRecover :: Text -> (SyntaxNode, [SyntaxError])@,\n--   which always returns a tree;\n-- * one constant per syntax kind, @syntaxKindExpr@ and @syntaxKindNum@, and\n--   @nameOfSyntaxKind@ and @isTriviaSyntaxKind@;\n-- * typed wrappers for the nodes of each rule, @newtype ExprSyntax@, with a\n--   cast @castExprSyntax :: SyntaxNode -> Maybe ExprSyntax@ and one accessor\n--   per binding, such as @exprLhs :: ExprSyntax -> Maybe ExprSyntax@ for a\n--   binding @lhs:Expr@.\n--\n-- The children of a node are found with 'syntaxChildren' and\n-- 'syntaxChildrenWithTokens', or by their labels (the binding names of the\n-- grammar) with 'labeledNode' and the functions next to it:\n--\n-- @\n-- case parseSyntax src of\n--   Left err -> TIO.putStrLn (renderParseError err)\n--   Right root -> do\n--     TIO.putStr (debugTree nameOfSyntaxKind root)\n--     print (syntaxText root == src)  -- always True\n--     print [syntaxRange n | n <- syntaxChildren root, syntaxKind n == syntaxKindExpr]\n-- @\nmodule Peg.Runtime.Syntax\n  ( -- * Kinds\n    SyntaxKind (..)\n  , textKind\n  , errorKind\n    -- * Green trees\n  , GreenNode\n  , GreenToken\n  , GreenElement (..)\n  , greenNodeKind\n  , greenNodeChildren\n  , greenTokenKind\n  , greenTokenText\n    -- * Syntax trees\n  , SyntaxNode\n  , SyntaxToken\n  , SyntaxElement (..)\n  , syntaxKind\n  , syntaxLabel\n  , syntaxRange\n  , syntaxText\n  , syntaxParent\n  , syntaxChildren\n  , syntaxChildrenWithTokens\n  , syntaxTokens\n  , syntaxPos\n  , tokenKind\n  , tokenLabel\n  , tokenRange\n  , tokenText\n  , tokenParent\n  , elementKind\n  , elementLabel\n    -- * Labelled children\n  , labeledElements\n  , labeledNode\n  , labeledNodes\n  , labeledToken\n  , labeledTokens\n    -- * Display\n  , debugTree\n    -- * Building (used by generated code)\n  , Child (..)\n  , setLabel\n  , syntaxRoot\n  ) where\n\nimport Data.Maybe (listToMaybe)\nimport Data.Text (Text)\nimport qualified Data.Text as T\nimport qualified Data.Text.Unsafe as TU\nimport Peg.Runtime.Position (LineIndex, Pos, lineIndex, posIn)\n\n-- | The kind of a node or token. Generated modules export one constant per\n-- rule that is not @%inline@, named @syntaxKind@ followed by the rule name,\n-- and @nameOfSyntaxKind@ to name a kind; 'textKind' (0) and 'errorKind' (1)\n-- are fixed.\nnewtype SyntaxKind = SyntaxKind Int\n  deriving (Eq, Ord, Show)\n\n-- | Tokens of text matched by terminals outside @%token@ rules: the text\n-- between the children of a node.\ntextKind :: SyntaxKind\ntextKind = SyntaxKind 0\n\n-- | Error nodes: the ranges that error recovery skipped (ADR 0021). The\n-- recovering entry points (@parseSyntaxRecover@) produce them.\nerrorKind :: SyntaxKind\nerrorKind = SyntaxKind 1\n\n-- Green trees ------------------------------------------------------------------\n\n-- | An immutable node: its kind, the length of its text in bytes, and its\n-- children with their labels. It has no position, so it can be shared.\ndata GreenNode = GreenNode\n  { gnKind :: !SyntaxKind\n  , gnLength :: !Int\n  , gnChildren :: [(Maybe Text, GreenElement)]\n  }\n\n-- | An immutable token: its kind and its text.\ndata GreenToken = GreenToken\n  { gtKind :: !SyntaxKind\n  , gtText :: !Text\n  }\n\n-- | A child of a green node.\ndata GreenElement = GreenNodeElement GreenNode | GreenTokenElement GreenToken\n\n-- | The kind of a green node.\ngreenNodeKind :: GreenNode -> SyntaxKind\ngreenNodeKind = gnKind\n\n-- | Children with their labels (the binding names of the grammar).\ngreenNodeChildren :: GreenNode -> [(Maybe Text, GreenElement)]\ngreenNodeChildren = gnChildren\n\n-- | The kind of a green token.\ngreenTokenKind :: GreenToken -> SyntaxKind\ngreenTokenKind = gtKind\n\n-- | The text of a green token.\ngreenTokenText :: GreenToken -> Text\ngreenTokenText = gtText\n\nelementLength :: GreenElement -> Int\nelementLength (GreenNodeElement n) = gnLength n\nelementLength (GreenTokenElement t) = TU.lengthWord8 (gtText t)\n\n-- Syntax trees -----------------------------------------------------------------\n\ndata Source = Source\n  { srcText :: Text\n  , srcLines :: LineIndex\n  }\n\n-- | A node with its absolute position and parent.\ndata SyntaxNode = SyntaxNode\n  { snGreen :: GreenNode\n  , snOffset :: !Int\n  , snLabel :: Maybe Text\n  , snParent :: Maybe SyntaxNode\n  , snSource :: Source\n  }\n\n-- | A token with its absolute position and parent.\ndata SyntaxToken = SyntaxToken\n  { stGreen :: GreenToken\n  , stOffset :: !Int\n  , stLabel :: Maybe Text\n  , stParent :: SyntaxNode\n  }\n\n-- | A child of a node: a node or a token.\ndata SyntaxElement = NodeElement SyntaxNode | TokenElement SyntaxToken\n\ninstance Show SyntaxNode where\n  show n = \"SyntaxNode \" <> show (syntaxKind n) <> \" \" <> show (syntaxRange n)\n\ninstance Show SyntaxToken where\n  show t = \"SyntaxToken \" <> show (tokenKind t) <> \" \" <> show (tokenText t)\n\ninstance Show SyntaxElement where\n  show (NodeElement n) = show n\n  show (TokenElement t) = show t\n\ninstance Eq SyntaxNode where\n  a == b = snOffset a == snOffset b && syntaxRange a == syntaxRange b && syntaxKind a == syntaxKind b\n\ninstance Eq SyntaxToken where\n  a == b = stOffset a == stOffset b && tokenKind a == tokenKind b && tokenText a == tokenText b\n\ninstance Eq SyntaxElement where\n  NodeElement a == NodeElement b = a == b\n  TokenElement a == TokenElement b = a == b\n  _ == _ = False\n\n-- | The kind of a node.\nsyntaxKind :: SyntaxNode -> SyntaxKind\nsyntaxKind = gnKind . snGreen\n\n-- | The label of the node in its parent, if a binding produced it.\nsyntaxLabel :: SyntaxNode -> Maybe Text\nsyntaxLabel = snLabel\n\n-- | Byte offsets: start inclusive, end exclusive.\nsyntaxRange :: SyntaxNode -> (Int, Int)\nsyntaxRange n = (snOffset n, snOffset n + gnLength (snGreen n))\n\n-- | The text of the node, made from its tokens.\nsyntaxText :: SyntaxNode -> Text\nsyntaxText = T.concat . map tokenText . syntaxTokens\n\n-- | The parent of a node. The root has none.\nsyntaxParent :: SyntaxNode -> Maybe SyntaxNode\nsyntaxParent = snParent\n\n-- | Child nodes, in order.\nsyntaxChildren :: SyntaxNode -> [SyntaxNode]\nsyntaxChildren n = [c | NodeElement c <- syntaxChildrenWithTokens n]\n\n-- | Child nodes and tokens, in order.\nsyntaxChildrenWithTokens :: SyntaxNode -> [SyntaxElement]\nsyntaxChildrenWithTokens n = go (snOffset n) (gnChildren (snGreen n))\n  where\n    go _ [] = []\n    go off ((label, e) : rest) =\n      let el = case e of\n            GreenNodeElement g -> NodeElement (SyntaxNode g off label (Just n) (snSource n))\n            GreenTokenElement t -> TokenElement (SyntaxToken t off label n)\n       in el : go (off + elementLength e) rest\n\n-- | All tokens below the node, in order.\nsyntaxTokens :: SyntaxNode -> [SyntaxToken]\nsyntaxTokens root = go root []\n  where\n    -- An accumulator keeps this linear in the size of deep trees.\n    go n acc = foldr step acc (syntaxChildrenWithTokens n)\n    step (TokenElement t) acc = t : acc\n    step (NodeElement c) acc = go c acc\n\n-- | The line and column of a byte offset in the parsed input.\nsyntaxPos :: SyntaxNode -> Int -> Pos\nsyntaxPos n = posIn (srcText s) (srcLines s)\n  where\n    s = snSource n\n\n-- | The kind of a token.\ntokenKind :: SyntaxToken -> SyntaxKind\ntokenKind = gtKind . stGreen\n\n-- | The label of the token in its parent, if a binding produced it.\ntokenLabel :: SyntaxToken -> Maybe Text\ntokenLabel = stLabel\n\n-- | Byte offsets: start inclusive, end exclusive.\ntokenRange :: SyntaxToken -> (Int, Int)\ntokenRange t = (stOffset t, stOffset t + TU.lengthWord8 (gtText (stGreen t)))\n\n-- | The text of a token.\ntokenText :: SyntaxToken -> Text\ntokenText = gtText . stGreen\n\n-- | The node that contains a token.\ntokenParent :: SyntaxToken -> SyntaxNode\ntokenParent = stParent\n\n-- | The kind of a node or token.\nelementKind :: SyntaxElement -> SyntaxKind\nelementKind (NodeElement n) = syntaxKind n\nelementKind (TokenElement t) = tokenKind t\n\n-- | The label of a node or token in its parent.\nelementLabel :: SyntaxElement -> Maybe Text\nelementLabel (NodeElement n) = syntaxLabel n\nelementLabel (TokenElement t) = tokenLabel t\n\n-- Labelled children ------------------------------------------------------------\n\n-- | Children with a label, skipping elements whose kind satisfies the\n-- trivia predicate.\nlabeledElements :: (SyntaxKind -> Bool) -> Text -> SyntaxNode -> [SyntaxElement]\nlabeledElements isTrivia label n =\n  [e | e <- syntaxChildrenWithTokens n, elementLabel e == Just label, not (isTrivia (elementKind e))]\n\n-- | The first child node with a label and kind.\nlabeledNode :: SyntaxKind -> Text -> SyntaxNode -> Maybe SyntaxNode\nlabeledNode k label = listToMaybe . labeledNodes k label\n\n-- | All child nodes with a label and kind.\nlabeledNodes :: SyntaxKind -> Text -> SyntaxNode -> [SyntaxNode]\nlabeledNodes k label n = [c | NodeElement c <- syntaxChildrenWithTokens n, syntaxLabel c == Just label, syntaxKind c == k]\n\n-- | The first child token with a label and kind.\nlabeledToken :: SyntaxKind -> Text -> SyntaxNode -> Maybe SyntaxToken\nlabeledToken k label = listToMaybe . labeledTokens k label\n\n-- | All child tokens with a label and kind.\nlabeledTokens :: SyntaxKind -> Text -> SyntaxNode -> [SyntaxToken]\nlabeledTokens k label n = [t | TokenElement t <- syntaxChildrenWithTokens n, tokenLabel t == Just label, tokenKind t == k]\n\n-- Display ------------------------------------------------------------------------\n\n-- | An indented dump of the tree, one element per line, as @Kind\\@start..end@\n-- with the text of tokens and the labels of children.\ndebugTree :: (SyntaxKind -> Text) -> SyntaxNode -> Text\ndebugTree name root = T.unlines (nodeLines 0 Nothing root [])\n  where\n    nodeLines depth label n acc =\n      line depth label (name (syntaxKind n)) (syntaxRange n) Nothing\n        : foldr (elementLines (depth + 1)) acc (syntaxChildrenWithTokens n)\n    elementLines depth (NodeElement c) acc = nodeLines depth (syntaxLabel c) c acc\n    elementLines depth (TokenElement t) acc = line depth (tokenLabel t) (name (tokenKind t)) (tokenRange t) (Just (tokenText t)) : acc\n    line :: Int -> Maybe Text -> Text -> (Int, Int) -> Maybe Text -> Text\n    line depth label kind (s, e) text =\n      T.concat\n        [ T.replicate (2 * depth) \" \"\n        , maybe \"\" (<> \": \") label\n        , kind\n        , \"@\"\n        , T.pack (show s)\n        , \"..\"\n        , T.pack (show e)\n        , maybe \"\" (\\t -> \" \" <> T.pack (show t)) text\n        ]\n\n-- Building -----------------------------------------------------------------------\n\n-- | What a rule invocation contributes to the tree while parsing: nodes and\n-- tokens with byte offsets and labels. Terminal matches are not recorded;\n-- the gaps between children become text tokens when the tree is built.\ndata Child\n  = CNode !SyntaxKind !Int !Int [Child] !(Maybe Text)\n  | CToken !SyntaxKind !Int !Int !(Maybe Text)\n\n-- | Label a child unless it already has a label.\nsetLabel :: Text -> Child -> Child\nsetLabel l c = case c of\n  CNode k s e ks Nothing -> CNode k s e ks (Just l)\n  CToken k s e Nothing -> CToken k s e (Just l)\n  _ -> c\n\n-- | The tree of a whole input. If the children are not a single node that\n-- covers the input, they are wrapped in a node of the given kind.\nsyntaxRoot :: Text -> SyntaxKind -> [Child] -> SyntaxNode\nsyntaxRoot input k kids = SyntaxNode green 0 Nothing Nothing (Source input (lineIndex input))\n  where\n    len = TU.lengthWord8 input\n    top = case kids of\n      [c@(CNode _ 0 e _ _)] | e == len -> c\n      _ -> CNode k 0 len kids Nothing\n    green = case build input top of\n      GreenNodeElement g -> g\n      GreenTokenElement t -> GreenNode k (TU.lengthWord8 (gtText t)) [(Nothing, GreenTokenElement t)]\n\nbuild :: Text -> Child -> GreenElement\nbuild input c = case c of\n  CToken k s e _ -> GreenTokenElement (GreenToken k (slice s e))\n  CNode k s e kids _ -> GreenNodeElement (GreenNode k (e - s) (go s kids))\n    where\n      go pos [] = gap pos e\n      go pos (x : xs) =\n        let (xs', xe) = childRange x\n         in gap pos xs' ++ [(childLabel x, build input x)] ++ go xe xs\n  where\n    slice s e = TU.takeWord8 (e - s) (TU.dropWord8 s input)\n    gap s e\n      | e > s = [(Nothing, GreenTokenElement (GreenToken textKind (slice s e)))]\n      | otherwise = []\n    childRange (CNode _ s e _ _) = (s, e)\n    childRange (CToken _ s e _) = (s, e)\n    childLabel (CNode _ _ _ _ l) = l\n    childLabel (CToken _ _ _ l) = l\n")
  ]

-- | @app/Pretty.hs@.
prettySource :: String
prettySource = "{-# LANGUAGE LambdaCase #-}\n\n-- | Indenting the output of 'show' along its brackets (ADR 0036). The\n-- tokens are kept: only the spaces between them change. peg-hs parse\n-- compiles this module, which depends only on base, with the parser it\n-- generates.\nmodule Pretty (pretty, readable) where\n\nimport Data.Char (chr, isDigit, isPrint, isSpace)\n\n-- | The output of 'show' with the characters outside ASCII of its string\n-- literals as themselves, such as @\\\"\12354\\\"@ for @\\\"\\\\12354\\\"@, so that text in\n-- any language can be read (ADR 0045). Characters that are not printable\n-- keep their escapes.\nreadable :: String -> String\nreadable = outside\n  where\n    outside = \\case\n      [] -> []\n      '\"' : rest -> '\"' : inside rest\n      c : rest -> c : outside rest\n    inside = \\case\n      [] -> []\n      '\"' : rest -> '\"' : outside rest\n      '\\\\' : rest@(d : _)\n        | isDigit d ->\n            let (digits, rest') = span isDigit rest\n                n = read digits :: Int\n             in if length digits <= 7 && n >= 128 && n <= 0x10FFFF && isPrint (chr n)\n                  then chr n : inside (dropSeparator rest')\n                  else '\\\\' : digits <> inside rest'\n      '\\\\' : x : rest -> '\\\\' : x : inside rest\n      c : rest -> c : inside rest\n    -- \\& ends a numeric escape before a digit; a character needs no end.\n    dropSeparator = \\case\n      '\\\\' : '&' : rest -> rest\n      rest -> rest\n\n-- | The text laid out in lines of at most 80 characters where it can be:\n-- a group that does not fit has its elements on lines of their own.\npretty :: String -> String\npretty = unlines . layout 0 . parseNodes . tokenize\n\ndata Token = Token Bool String\n  -- ^ Whether spaces precede it, and its text.\n\ndata Node\n  = Atom Bool String\n  | Group Bool Char [Node] Char\n\nwidth :: Int\nwidth = 80\n\ntokenize :: String -> [Token]\ntokenize = go False\n  where\n    go _ [] = []\n    go sp s@(c : rest)\n      | isSpace c = go True rest\n      | c == '\"' = let (t, rest') = quoted '\"' rest in Token sp (c : t) : go False rest'\n      | c == '\\'' = let (t, rest') = character rest in Token sp (c : t) : go False rest'\n      | c `elem` \"()[]{},\" = Token sp [c] : go False rest\n      | otherwise = let (t, rest') = break (\\x -> isSpace x || x `elem` \"()[]{},\\\"\") s in Token sp t : go False rest'\n    quoted q s = case s of\n      '\\\\' : x : rest -> let (t, rest') = quoted q rest in ('\\\\' : x : t, rest')\n      x : rest\n        | x == q -> ([x], rest)\n        | otherwise -> let (t, rest') = quoted q rest in (x : t, rest')\n      [] -> ([], [])\n    -- A character literal, or a quote that is part of a name.\n    character s = case s of\n      '\\\\' : _ -> quoted '\\'' s\n      x : '\\'' : rest -> ([x, '\\''], rest)\n      _ -> let (t, rest) = break (\\x -> isSpace x || x `elem` \"()[]{},\\\"\") s in (t, rest)\n\nparseNodes :: [Token] -> [Node]\nparseNodes ts = let (ns, _) = nodes ts in ns\n  where\n    nodes [] = ([], [])\n    nodes (Token sp [o] : rest)\n      | o `elem` \"([{\" =\n          let (inner, rest') = nodes rest\n           in case rest' of\n                Token _ [c] : rest'' | c `elem` \")]}\" -> let (more, after) = nodes rest'' in (Group sp o inner c : more, after)\n                _ -> ([Group sp o inner ' '], rest')\n    nodes ts'@(Token _ [c] : _) | c `elem` \")]}\" = ([], ts')\n    nodes (Token sp t : rest) = let (more, after) = nodes rest in (Atom sp t : more, after)\n\n-- One line, with one space where there were spaces.\nflat :: [Node] -> String\nflat = concat . zipWith piece [0 :: Int ..]\n  where\n    piece i n = (if i > 0 && spaced n then \" \" else \"\") <> case n of\n      Atom _ t -> t\n      Group _ o inner c -> [o] <> flat inner <> [c | c /= ' ']\n    spaced = \\case\n      Atom sp _ -> sp\n      Group sp _ _ _ -> sp\n\n-- The lines of a sequence at an indentation; the first line starts at the\n-- indentation too.\nlayout :: Int -> [Node] -> [String]\nlayout ind ns\n  | ind + length (flat ns) <= width = [replicate ind ' ' <> flat ns]\n  | otherwise = case ns of\n      [Group _ o inner c] -> group ind o inner c\n      [n] -> [replicate ind ' ' <> flat [n]]\n      n : rest -> layout ind [n] <> concatMap (layout (ind + 2) . pure) rest\n      [] -> []\n\n-- A group that does not fit: its elements, separated by commas, on lines of\n-- their own, with the commas first.\ngroup :: Int -> Char -> [Node] -> Char -> [String]\ngroup ind o inner c =\n  case splitCommas inner of\n    [part] ->\n      -- No commas: the opening bracket starts the first line of the contents.\n      case layout (ind + 1) part of\n        first : rest -> (replicate ind ' ' <> [o] <> drop (ind + 1) first) : rest <> [replicate ind ' ' <> [c] | c /= ' ']\n        [] -> [replicate ind ' ' <> [o] <> [c | c /= ' ']]\n    parts ->\n      concat\n        [ case layout (ind + 2) part of\n            first : rest -> (replicate ind ' ' <> [if i == 0 then o else ','] <> \" \" <> drop (ind + 2) first) : rest\n            [] -> [replicate ind ' ' <> [if i == 0 then o else ',']]\n        | (i, part) <- zip [0 :: Int ..] parts\n        ]\n        <> [replicate ind ' ' <> [c] | c /= ' ']\n\nsplitCommas :: [Node] -> [[Node]]\nsplitCommas = go []\n  where\n    go acc [] = [reverse acc]\n    go acc (Atom _ \",\" : rest) = reverse acc : go [] rest\n    go acc (n : rest) = go (n : acc) rest\n"
